// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address newOwner) public {
        // The contract deploys with owner == address(0), so only address(0)
        // passes the onlyOwner modifier. Prank from that address to exercise
        // transferOwnership with a fuzzer-supplied newOwner.
        vm.prank(address(0));
        c.transferOwnership(newOwner);
        // Rule: for any input, ownership becomes exactly newOwner.
        assertTrue(c.owner() == newOwner);
    }
}
